view.renderTriage:
function renderTriage(opts) {
  // Self-contained: the kernel wraps each view fn in `new Function(...)`
  // so siblings (like a module-level _escLR helper) are NOT visible at
  // call time. HTML-escape helper is inlined here.
  function _escLR(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return null;
  var types = opts.types || [];
  var selected = opts.selected || "Other";
  var isRedline = !!opts.isRedline;
  var hasPlaybook = !!opts.hasPlaybook;
  var hasTemplate = !!opts.hasTemplate;
  var recommend = opts.recommend || { icon: "💡", lines: ["<strong>Configure & Launch</strong>"] };
  var onBack = opts.onBack || function () {};
  var onSubmit = opts.onSubmit || function () {};
  var onLegalRisks = opts.onLegalRisks || function () {};
  var onCompare = opts.onCompare || function () {};
  var onReviewRedlines = opts.onReviewRedlines || function () {};
  var onSettings = opts.onSettings || function () {};
  var onTypeChange = opts.onTypeChange || function () {};
  var onPaperChange = opts.onPaperChange || function () {};
  var onRevisedByChange = opts.onRevisedByChange || function () {};

  var typeOpts = types.map(function (t) {
    return '<option value="' + _escLR(t) + '"' + (t === selected ? " selected" : "") + ">" + _escLR(t) + "</option>";
  }).join("");

  var stepNumPaper = isRedline ? "03" : "02";
  var leftAccent = isRedline
    ? "linear-gradient(to bottom, #c62828, #1565c0)"
    : "#1565c0";
  var introCopy = isRedline
    ? "Revisions identified. Verify the context below to proceed."
    : "Confirm the agreement intent to initialize the high-fidelity review engine.";

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_lr_root";
  root.setAttribute("data-eli-view", "review-draft");
  root.innerHTML =
    // ── Top toolbar ────────────────────────────────────────────────
    '<div class="_eli3_lr_toolbar">' +
      '<button type="button" class="_eli3_lr_back" title="Back">' +
        '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M19 12H5M12 19l-7-7 7-7"/></svg>' +
        ' BACK' +
      '</button>' +
      '<div class="_eli3_lr_title">Legal Intelligence Engine</div>' +
    '</div>' +
    // ── Two-column grid ────────────────────────────────────────────
    '<div class="_eli3_lr_grid" id="_eli3_lr_grid">' +
      // LEFT COLUMN
      '<div class="_eli3_lr_left">' +
        '<div class="_eli3_lr_accent" style="background:' + leftAccent + ';"></div>' +
        '<div class="_eli3_lr_scroll">' +
          '<div>' +
            '<h2 class="_eli3_lr_h2">Configure Analysis</h2>' +
            '<p class="_eli3_lr_intro">' + _escLR(introCopy) + '</p>' +
          '</div>' +
          // Step 1 — Agreement type
          '<div class="_eli3_lr_card">' +
            '<div class="_eli3_lr_card_head">' +
              '<label class="_eli3_lr_step">01. Confirm Agreement Type</label>' +
              '<span class="_eli3_lr_badgerow" id="_eli3_lr_badgerow"></span>' +
            '</div>' +
            '<div class="_eli3_lr_selectwrap">' +
              '<select class="_eli3_lr_select" id="_eli3_lr_type">' + typeOpts + '</select>' +
              '<div class="_eli3_lr_caret">▼</div>' +
            '</div>' +
          '</div>' +
          // Step 2 — Who last revised? (redline mode only)
          (isRedline
            ? '<div class="_eli3_lr_card">' +
                '<label class="_eli3_lr_step _eli3_lr_step_block">02. Who last revised?</label>' +
                '<div class="_eli3_lr_choices">' +
                  '<label class="_eli3_lr_choice">' +
                    '<input type="radio" name="_eli3_lr_revised_by" value="colgate">' +
                    '<div class="_eli3_lr_tile" data-tile="revised-colgate">' +
                      '<div class="_eli3_lr_tile_icon">👤</div>' +
                      '<div class="_eli3_lr_tile_title">Colgate</div>' +
                      '<div class="_eli3_lr_tile_sub">Our Edits</div>' +
                    '</div>' +
                  '</label>' +
                  '<label class="_eli3_lr_choice">' +
                    '<input type="radio" name="_eli3_lr_revised_by" value="counterparty" checked>' +
                    '<div class="_eli3_lr_tile _eli3_lr_tile_active" data-tile="revised-counterparty">' +
                      '<div class="_eli3_lr_tile_icon">👥</div>' +
                      '<div class="_eli3_lr_tile_title">Counterparty</div>' +
                      '<div class="_eli3_lr_tile_sub">Their Markup</div>' +
                    '</div>' +
                  '</label>' +
                '</div>' +
              '</div>'
            : '') +
          // Step 3 (or 2) — Original Source
          '<div class="_eli3_lr_card">' +
            '<label class="_eli3_lr_step _eli3_lr_step_block">' + stepNumPaper + '. Original Source</label>' +
            '<div class="_eli3_lr_choices">' +
              '<label class="_eli3_lr_choice">' +
                '<input type="radio" name="_eli3_lr_paper" value="colgate"' + (isRedline ? '' : '') + '>' +
                '<div class="_eli3_lr_tile" data-tile="paper-colgate">' +
                  '<div class="_eli3_lr_tile_icon">🏢</div>' +
                  '<div class="_eli3_lr_tile_title">Colgate Paper</div>' +
                  '<div class="_eli3_lr_tile_sub">Colgate Template</div>' +
                '</div>' +
              '</label>' +
              '<label class="_eli3_lr_choice">' +
                '<input type="radio" name="_eli3_lr_paper" value="thirdparty"' + (isRedline ? '' : ' checked') + '>' +
                '<div class="_eli3_lr_tile' + (isRedline ? '' : ' _eli3_lr_tile_active') + '" data-tile="paper-thirdparty">' +
                  '<div class="_eli3_lr_tile_icon">🤝</div>' +
                  '<div class="_eli3_lr_tile_title">Third-Party</div>' +
                  '<div class="_eli3_lr_tile_sub">External Baseline</div>' +
                '</div>' +
              '</label>' +
            '</div>' +
          '</div>' +
        '</div>' +
        // Fixed footer button
        '<div class="_eli3_lr_footer">' +
          '<button type="button" class="_eli3_lr_settings_btn" id="_eli3_lr_settings_btn" title="Tool settings">⚙️</button>' +
          '<button type="button" class="_eli3_lr_submit" id="_eli3_lr_submit">Launch Analysis</button>' +
        '</div>' +
      '</div>' +
      // RIGHT COLUMN — Manual scans + ELI Recommends
      '<div class="_eli3_lr_right" id="_eli3_lr_right">' +
        '<div class="_eli3_lr_manual_stack">' +
          '<div class="_eli3_lr_eyebrow">Manual</div>' +
          '<button type="button" class="_eli3_lr_manual_btn" id="_eli3_lr_btn_risks">' +
            '<span class="_eli3_lr_manual_icon">🛡️</span>' +
            '<div class="_eli3_lr_manual_label">Legal Risks</div>' +
          '</button>' +
          '<button type="button" class="_eli3_lr_manual_btn" id="_eli3_lr_btn_compare">' +
            '<span class="_eli3_lr_manual_icon">⚖️</span>' +
            '<div class="_eli3_lr_manual_label">Compare Doc</div>' +
          '</button>' +
          '<button type="button" class="_eli3_lr_manual_btn" id="_eli3_lr_btn_redlines">' +
            '<span class="_eli3_lr_manual_icon">📝</span>' +
            '<div class="_eli3_lr_manual_label">Review Redlines</div>' +
          '</button>' +
        '</div>' +
        '<div class="_eli3_lr_recommend" id="_eli3_lr_recommend"></div>' +
      '</div>' +
    '</div>';

  mount.appendChild(root);

  // ─── Wire interactions ───────────────────────────────────────────
  function _byId(id) { return root.querySelector("#" + id); }

  _byId("_eli3_lr_grid"); // grid reference (no-op — exists for clarity)
  root.querySelector("._eli3_lr_back").onclick = onBack;
  _byId("_eli3_lr_submit").onclick = function () {
    var paperRadio = root.querySelector('input[name="_eli3_lr_paper"]:checked');
    var revisedRadio = root.querySelector('input[name="_eli3_lr_revised_by"]:checked');
    onSubmit({
      type: _byId("_eli3_lr_type").value,
      paperType: paperRadio ? paperRadio.value : "thirdparty",
      revisedBy: revisedRadio ? revisedRadio.value : null,
      isRedline: isRedline,
    });
  };
  _byId("_eli3_lr_btn_risks").onclick = function () { onLegalRisks(); };
  _byId("_eli3_lr_btn_compare").onclick = function () { onCompare(); };
  _byId("_eli3_lr_btn_redlines").onclick = function () { onReviewRedlines(); };
  var _setBtn = _byId("_eli3_lr_settings_btn");
  if (_setBtn) _setBtn.onclick = function () { onSettings(); };

  var typeSelect = _byId("_eli3_lr_type");
  typeSelect.onchange = function () {
    onTypeChange(typeSelect.value);
    _refreshBadge();
    _refreshRecommend();
  };

  // Tile highlighting + change callbacks for paper + revisedBy radios.
  function _wireRadioGroup(name, onChange) {
    var radios = root.querySelectorAll('input[name="' + name + '"]');
    Array.prototype.forEach.call(radios, function (r) {
      r.onchange = function () {
        // Update active-tile style.
        Array.prototype.forEach.call(radios, function (rr) {
          var tile = rr.parentNode.querySelector("._eli3_lr_tile");
          if (tile) tile.classList.toggle("_eli3_lr_tile_active", rr.checked);
        });
        onChange(r.value);
      };
    });
  }
  _wireRadioGroup("_eli3_lr_paper", function (val) {
    onPaperChange(val);
    _refreshBadge();
    _refreshRecommend();
  });
  if (isRedline) {
    _wireRadioGroup("_eli3_lr_revised_by", function (val) { onRevisedByChange(val); });
  }

  // Badge under the agreement type — "📗 Playbook Available" or
  // "📋 EI Template Available" depending on triage state.
  function _refreshBadge() {
    var row = _byId("_eli3_lr_badgerow");
    if (!row) return;
    row.innerHTML = "";
    var paperRadio = root.querySelector('input[name="_eli3_lr_paper"]:checked');
    var paperType = paperRadio ? paperRadio.value : "thirdparty";
    if (isRedline) {
      if (paperType !== "thirdparty" && hasPlaybook) {
        row.innerHTML = '<div class="_eli3_lr_badge _eli3_lr_badge_pb">📗 Playbook Available</div>';
      }
    } else {
      if (hasTemplate) {
        row.innerHTML = '<div class="_eli3_lr_badge _eli3_lr_badge_tpl">📋 EI Template Available</div>';
      }
    }
  }
  function _refreshRecommend() {
    var box = _byId("_eli3_lr_recommend");
    if (!box) return;
    box.innerHTML =
      '<div class="_eli3_lr_recommend_row">' +
        '<div class="_eli3_lr_recommend_icon">' + _escLR(recommend.icon) + '</div>' +
        '<div>' +
          '<div class="_eli3_lr_recommend_eyebrow">ELI Recommends</div>' +
          '<div class="_eli3_lr_recommend_lines">' + (recommend.lines || []).join("<br>") + '</div>' +
          '<div class="_eli3_lr_recommend_hint">Click <strong>Launch Analysis</strong> to begin</div>' +
        '</div>' +
      '</div>';
  }
  _refreshBadge();
  _refreshRecommend();

  // Public surface — init can swap state + re-render the recommend box
  // (e.g., after playbook/template data resolves).
  return {
    setHasPlaybook: function (v) { hasPlaybook = !!v; _refreshBadge(); _refreshRecommend(); },
    setHasTemplate: function (v) { hasTemplate = !!v; _refreshBadge(); _refreshRecommend(); },
    setRecommend: function (r) { recommend = r || recommend; _refreshRecommend(); },
    refresh: function () { _refreshBadge(); _refreshRecommend(); },
  };
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };
  var bundle = eli.tools._loaded["legal_review"];
  if (!bundle) return;
  var efns = bundle._eliEngineFns || {};
  var vfns = bundle._eliViewFns || {};
  var buildAgreementTypeList = efns.buildAgreementTypeList;
  var recommendScan          = efns.recommendScan;
  var renderTriage           = vfns.renderTriage;
  if (!buildAgreementTypeList || !recommendScan || !renderTriage) {
    eli.log.event("tool", "legal_review_load_failed", {
      hasBuild: !!buildAgreementTypeList, hasReco: !!recommendScan, hasView: !!renderTriage,
    });
    return;
  }

  // ─── Doc state read ─────────────────────────────────────────────
  // Counts tracked changes (sets isRedline) + detects the agreement
  // type via the host's helper if available. Cheap relative to body
  // text — one property load per call.
  function _readDocState() {
    var out = { hasRedlines: false, redlineCount: 0, docType: "Other" };
    if (!eli.host || !eli.host.runRaw) return Promise.resolve(out);
    return eli.host.runRaw("legal_review:state_scan", function (context) {
      var body = context.document.body;
      var changes = body.getTrackedChanges();
      changes.load("items");
      return context.sync().then(function () {
        out.redlineCount = (changes.items || []).length;
        out.hasRedlines = out.redlineCount > 0;
        return out;
      });
    }).then(function (state) {
      // Use the kernel host's detector if it exposes one; else leave
      // "Other" as the safe default.
      if (eli.host && typeof eli.host.detectAgreementType === "function") {
        return eli.host.detectAgreementType().then(function (t) {
          state.docType = t || state.docType;
          return state;
        }).catch(function () { return state; });
      }
      return state;
    }).catch(function () { return out; });
  }

  // ─── Playbook + template availability ───────────────────────────
  // Mirrors v2 runLegalReview line 17416-17439. Both are best-effort
  // — if neither store loads, the recommend box just shows the generic
  // scan suggestion.
  function _loadPlaybookMap() {
    if (!eli.storage || typeof eli.storage.getAll !== "function") return Promise.resolve({});
    return eli.storage.getAll("playbooks").then(function (rows) {
      var map = {};
      (rows || []).forEach(function (r) {
        if (r && r.id && String(r.id).charAt(0) !== "_") {
          map[String(r.agreementType || r.id)] = r;
        }
      });
      return map;
    }).catch(function () { return {}; });
  }
  function _loadTemplateList() {
    if (!eli.storage || typeof eli.storage.getAll !== "function") return Promise.resolve([]);
    return eli.storage.getAll("templates").then(function (rows) {
      return (rows || []).filter(function (r) {
        return r && r.id && String(r.id).charAt(0) !== "_";
      });
    }).catch(function () { return []; });
  }
  // Load the agreement-types catalog (with aliases) for fuzzy matching.
  // Templates can be tagged with any alias ("NDA", "Confidentiality",
  // "Mutual NDA") while the dropdown shows the canonical label
  // ("Non-Disclosure Agreement") — strict equality misses all of those.
  function _loadAgreementCatalog() {
    if (!eli.storage || typeof eli.storage.getAll !== "function") return Promise.resolve([]);
    return eli.storage.getAll("agreement_types").then(function (rows) {
      return (rows || []).filter(function (r) {
        return r && r.label && (!r.id || String(r.id).charAt(0) !== "_");
      });
    }).catch(function () { return []; });
  }
  // Match templateType against docType using the alias catalog. Falls
  // back to substring + exact match when the catalog is empty.
  function _matchesAgreementType(catalog, templateType, docType) {
    if (!templateType || !docType) return false;
    var a = String(templateType).trim().toLowerCase();
    var b = String(docType).trim().toLowerCase();
    if (a === b) return true;
    if (a.indexOf(b) !== -1 || b.indexOf(a) !== -1) return true;
    if (!Array.isArray(catalog) || !catalog.length) return false;
    function groupFor(val) {
      for (var i = 0; i < catalog.length; i++) {
        var cat = catalog[i];
        var lbl = String(cat.label || "").toLowerCase();
        var aliases = (cat.aliases || []).map(function (x) { return String(x).toLowerCase(); });
        if (lbl === val) return aliases.concat([lbl]);
        for (var j = 0; j < aliases.length; j++) {
          if (val.indexOf(aliases[j]) !== -1 || aliases[j].indexOf(val) !== -1) {
            return aliases.concat([lbl]);
          }
        }
      }
      return null;
    }
    var gA = groupFor(a), gB = groupFor(b);
    if (gA && gB && gA[gA.length - 1] === gB[gB.length - 1]) return true;
    if (gA) for (var k = 0; k < gA.length; k++) { if (b.indexOf(gA[k]) !== -1 || gA[k].indexOf(b) !== -1) return true; }
    if (gB) for (var k2 = 0; k2 < gB.length; k2++) { if (a.indexOf(gB[k2]) !== -1 || gB[k2].indexOf(a) !== -1) return true; }
    return false;
  }
  function _hasPlaybookForType(map, typeName, catalog) {
    if (!map) return false;
    var keys = Object.keys(map);
    for (var i = 0; i < keys.length; i++) {
      if (_matchesAgreementType(catalog, keys[i], typeName)) return true;
    }
    return false;
  }
  function _hasTemplateForType(list, typeName, catalog) {
    if (!Array.isArray(list)) return false;
    for (var i = 0; i < list.length; i++) {
      var tType = list[i].agreementType || list[i].type || "";
      if (tType && _matchesAgreementType(catalog, tType, typeName)) return true;
    }
    return false;
  }

  // ─── Open the landing page ──────────────────────────────────────
  function _open() {
    eli.log.event("tool", "legal_review_open_called", {});
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedLegalReview"); } catch (e) {}
    try {
      var cur = eli.fsm.getCurrent ? eli.fsm.getCurrent() : null;
      if (cur === "idle") eli.fsm.transition("scanning");
    } catch (e) {}
    var mount = document.getElementById("_eli3_dashboard_root");
    if (!mount) {
      eli.log.event("tool", "legal_review_open_no_mount", {});
      if (typeof showToast === "function") showToast("Dashboard root missing — try reopening ELI", "err");
      return;
    }

    Promise.all([
      _readDocState(),
      _loadPlaybookMap(),
      _loadTemplateList(),
      _loadAgreementCatalog(),
    ]).then(function (r) {
      eli.log.event("tool", "legal_review_data_loaded", {
        isRedline: r[0] && r[0].hasRedlines, docType: r[0] && r[0].docType,
        playbooks: Object.keys(r[1] || {}).length,
        templates: (r[2] || []).length,
        catalog: (r[3] || []).length,
      });
      return r;
    }).then(function (r) {
      var state = r[0] || { hasRedlines: false, docType: "Other" };
      var pbMap = r[1] || {};
      var tmplList = r[2] || [];
      var agCatalog = r[3] || [];
      var typeList = buildAgreementTypeList(state.docType);

      // State the view holds — mutated by paper/type changes.
      var currentType = typeList.selected;
      var currentPaperType = state.hasRedlines ? "counterparty" : "thirdparty";
      var currentRevisedBy = state.hasRedlines ? "counterparty" : null;

      function _hasPb() { return _hasPlaybookForType(pbMap, currentType, agCatalog); }
      function _hasTpl() { return _hasTemplateForType(tmplList, currentType, agCatalog); }
      function _reco() {
        return recommendScan({
          isRedline: state.hasRedlines,
          paperType: currentPaperType,
          hasPlaybook: _hasPb(),
          hasTemplate: _hasTpl(),
        });
      }

      var ui = renderTriage({
        mount: mount,
        types: typeList.types,
        selected: typeList.selected,
        isRedline: state.hasRedlines,
        hasPlaybook: _hasPb(),
        hasTemplate: _hasTpl(),
        recommend: _reco(),
        onBack: function () {
          try { eli.fsm.transition("idle"); } catch (e) {}
          if (eli.dashboard && typeof eli.dashboard.goHome === "function") eli.dashboard.goHome();
          else if (eli.dashboard && typeof eli.dashboard.render === "function") eli.dashboard.render();
        },
        onTypeChange: function (val) {
          currentType = val;
          // Stash on window so legacy v2 consumers can read it.
          try { window._eliDocType = val; } catch (e) {}
          ui.setHasPlaybook(_hasPb());
          ui.setHasTemplate(_hasTpl());
          ui.setRecommend(_reco());
        },
        onPaperChange: function (val) {
          currentPaperType = val;
          ui.setRecommend(_reco());
        },
        onRevisedByChange: function (val) { currentRevisedBy = val; },
        onSubmit: function (formState) {
          _launchAnalysis(formState, {
            hasPlaybook: _hasPb(),
            hasTemplate: _hasTpl(),
            pbMap: pbMap,
            tmplList: tmplList,
            agCatalog: agCatalog,
          });
        },
        onLegalRisks: function () {
          _dispatchTo("legal_risks", "app_legal_risks", "Legal Risks");
        },
        onCompare: function () {
          _dispatchTo("compare", "app_compare", "Compare");
        },
        onReviewRedlines: function () {
          _dispatchTo("review_redlines", "app_review_redlines", "Review Redlines");
        },
        onSettings: function () {
          _showSettingsMenu();
        },
      });
    }).catch(function (err) {
      eli.log.event("tool", "legal_review_open_failed", { msg: err && err.message });
      if (typeof showToast === "function") {
        showToast("Legal Review failed: " + (err && err.message || "unknown"), "err");
      }
    });
  }

  // Safe tile-dispatch wrapper. Three layered safety nets so a click
  // on Launch Analysis / Legal Risks / Compare / Review Redlines is
  // never a silent no-op:
  //
  //   1. Try the registered v3 handler. Catch sync throws + wrap any
  //      returned Promise so an async rejection surfaces as a toast
  //      instead of an unhandled rejection in the console.
  //   2. If the handler isn't registered (tool not installed),
  //      auto-open the Downloads dialog so the user can install with
  //      one click. Matches the trophy_gallery fallback pattern.
  //   3. If the Downloads dialog isn't available either, fall back to
  //      a plain toast with instructions.
  //
  // toolId stashed so the future "install this tool" flow can offer
  // direct installation when the user clicks the toast.
  function _dispatchTo(toolId, catalogId, friendlyName) {
    function _runHandler() {
      var handler = eli.get && eli.get("tile", catalogId);
      if (typeof handler !== "function") return false;
      var result;
      try {
        result = handler();
      } catch (e) {
        eli.log.event("tool", "legal_review_dispatch_threw", { tool: toolId, msg: e && e.message });
        if (typeof showToast === "function") {
          showToast(friendlyName + " failed: " + (e && e.message || "unknown error"), "err");
        }
        return true;
      }
      if (result && typeof result.then === "function") {
        result.catch(function (err) {
          eli.log.event("tool", "legal_review_dispatch_rejected", { tool: toolId, msg: err && err.message });
          if (typeof showToast === "function") {
            showToast(friendlyName + " failed: " + (err && err.message || "unknown error"), "err");
          }
        });
      }
      return true;
    }
    // Fast path — tile handler already registered (boot-tier tools, or
    // preload-tier that finished eval'ing). Run synchronously.
    if (_runHandler()) return;
    // Lazy path — preload/demand tool hasn't eval'd yet. Tell the
    // kernel to load it, then retry. If the bundle isn't even installed
    // in IDB, ensureLoaded resolves false and we open Downloads.
    var ensureP = (eli.tools && typeof eli.tools.ensureLoaded === "function")
      ? eli.tools.ensureLoaded(toolId)
      : Promise.resolve(false);
    ensureP.then(function (ok) {
      if (_runHandler()) return;
      // Truly missing — bundle not installed in IDB. Open Downloads.
      eli.log.event("tool", "legal_review_dispatch_missing", { tool: toolId, ensureLoaded: !!ok });
      if (typeof showToast === "function") {
        showToast(friendlyName + " isn't installed yet — opening Downloads…", "info");
      }
      if (eli.dashboard && typeof eli.dashboard.showDownloadsDialog === "function") {
        try { eli.dashboard.showDownloadsDialog(); return; } catch (e) {}
      }
      if (typeof showToast === "function") {
        showToast(friendlyName + " not installed — open Settings → Check for Updates", "warn");
      }
    });
  }

  // Consolidated settings overlay — opens each sub-tool's settings
  // dialog via its tile_settings channel. Skips compare per scope.
  function _showSettingsMenu() {
    var ov = document.createElement("div");
    ov.className = "eli-overlay";
    ov.style.cssText = "position:fixed;inset:0;z-index:99999;background:rgba(15,23,42,0.55);display:flex;align-items:center;justify-content:center;padding:20px;font-family:Inter,'Segoe UI',system-ui,sans-serif;";
    function _open(channel, key) {
      var h = eli.get && eli.get(channel, key);
      if (typeof h === "function") {
        ov.remove();
        try { h(); } catch (e) {
          if (typeof showToast === "function") showToast("Settings failed: " + (e && e.message || "unknown"), "err");
        }
      } else if (typeof showToast === "function") {
        showToast("Settings not available — tool may not be installed", "warn");
      }
    }
    ov.innerHTML =
      '<div style="background:#fff;width:min(420px,96vw);border:1px solid #cbd5e1;box-shadow:0 24px 60px rgba(15,23,42,0.45);">' +
        '<div style="padding:14px 18px;background:linear-gradient(135deg,#0d1b2a,#1b263b);color:#fff;">' +
          '<div style="font:800 11px/1 Inter,sans-serif;letter-spacing:0.12em;text-transform:uppercase;color:#c9a227;">Settings</div>' +
          '<div style="font:800 17px/1.2 Inter,sans-serif;margin-top:2px;">Legal Review tools</div>' +
        '</div>' +
        '<div style="padding:12px 14px;display:flex;flex-direction:column;gap:8px;">' +
          '<button type="button" id="_eli3_lr_settings_lr"  style="text-align:left;padding:12px 14px;background:#fff;border:1px solid #c5d4ee;border-left:4px solid #1565c0;cursor:pointer;font:600 13px/1.3 Inter,sans-serif;">📚 Manage Risk Rules</button>' +
          '<button type="button" id="_eli3_lr_settings_rr"  style="text-align:left;padding:12px 14px;background:#fff;border:1px solid #c5d4ee;border-left:4px solid #1565c0;cursor:pointer;font:600 13px/1.3 Inter,sans-serif;">📝 Review Redlines settings</button>' +
          '<button type="button" id="_eli3_lr_settings_close" style="margin-top:6px;padding:8px 12px;background:#f1f5f9;border:1px solid #cbd5e1;cursor:pointer;font:600 11px/1.3 Inter,sans-serif;color:#475569;">Close</button>' +
        '</div>' +
      '</div>';
    document.body.appendChild(ov);
    ov.querySelector("#_eli3_lr_settings_lr").onclick = function () { _open("tile_settings", "app_legal_risks"); };
    ov.querySelector("#_eli3_lr_settings_rr").onclick = function () { _open("tile_settings", "app_review_redlines"); };
    ov.querySelector("#_eli3_lr_settings_close").onclick = function () { ov.remove(); };
    ov.onclick = function (e) { if (e.target === ov) ov.remove(); };
  }

  // Launch Analysis routing. Picks the right downstream tool based on
  // triage state. Mirrors v2 submitReviewDraft (line 17443+).
  function _launchAnalysis(formState, ctx) {
    var isRedline = !!formState.isRedline;
    var paperType = formState.paperType || "thirdparty";
    // Stash hints v2 consumers used to read.
    try {
      window._isFromReviewDraftConfig = true;
      window._eliDocType = formState.type;
      window._eliDisablePlaybookForReview = (isRedline && paperType === "thirdparty");
    } catch (e) {}
    if (isRedline) {
      // Redline mode → Review Redlines flow.
      // BUG FIX 2026-05-12: was dispatching to redline_email_pack (the
      // email-generators helper), which has no tile handler — Launch
      // Analysis silently did nothing on redline docs. Route to the
      // actual Review Redlines tool.
      _dispatchTo("review_redlines", "app_review_redlines", "Review Redlines");
      return;
    }
    // 2026-05-13 composite refactor: clean doc + template + compare
    // installed = run BOTH tools in parallel on a composite landing page
    // with two collapsible cards. Replaces the old "compare-leads, then
    // chain-to-risks" handoff which broke whenever the cross-tool baton
    // logic regressed (most recently today). Each tool now runs in its
    // own card; either can fail without breaking the other.
    if (paperType !== "colgate" && ctx.hasTemplate &&
        eli.get && typeof eli.get("tile", "app_compare") === "function") {
      _launchCompositeReview(formState, ctx);
      return;
    }
    _dispatchTo("legal_risks", "app_legal_risks", "Legal Risks");
  }

  // 2026-05-13 composite landing renderer. Builds the page chrome with
  // two cards (Legal Risks + Compare), fires the two scoped-mount entries
  // in parallel, populates each card header summary as it resolves. Each
  // card is independently collapsible. The current legal_risks UI lives
  // inside its card body when expanded; same for compare.
  function _launchCompositeReview(formState, ctx) {
    var out = document.getElementById("output");
    if (!out) {
      if (typeof showToast === "function") showToast("Dashboard root missing", "err");
      return;
    }
    out.innerHTML = "";
    out.classList.remove("hidden");
    var RISKS_CARD = "_eli3_lr_composite_risks_body";
    var COMPARE_CARD = "_eli3_lr_composite_compare_body";
    var RISKS_HEADER = "_eli3_lr_composite_risks_header_summary";
    var COMPARE_HEADER = "_eli3_lr_composite_compare_header_summary";

    out.innerHTML =
      '<div class="_eli3_lr_composite_page">' +
        '<div class="_eli3_lr_composite_pagehead">' +
          '<div class="_eli3_lr_composite_eyebrow">COMBINED ANALYSIS</div>' +
          '<div class="_eli3_lr_composite_title">📊 Legal Risks + 📑 Compare</div>' +
          '<div class="_eli3_lr_composite_sub">Both reviews run in parallel. Click any header to expand.</div>' +
        '</div>' +
        _cardShell("risks", "⚖", "Legal Risks", RISKS_CARD, RISKS_HEADER, true) +
        _cardShell("compare", "📑", "Compare to Template", COMPARE_CARD, COMPARE_HEADER, true) +
      '</div>';

    _wireCardToggle("risks");
    _wireCardToggle("compare");

    // Pick template by type when possible — falls back to the first
    // template installed for the agreement type, else lets compare
    // open its picker.
    var template = (ctx.tmplList || []).find(function (t) {
      var tType = t.agreementType || t.type || "";
      return tType && _matchesAgreementType(ctx.agCatalog || [], tType, formState.type);
    });
    var comparePayload = template ? { template: template } : null;
    var compareMode = template ? "template" : "new";
    // 2026-05-13 diagnostics: surfaces which template (if any) matched
    // and what payload shape we're handing to compare. Critical for
    // debugging "compare didn't fire" reports — turn on ELI_DEBUG and
    // inspect the event log.
    eli.log.event("tool", "legal_review_composite_template_pick", {
      formStateType: formState.type,
      tmplListLen: (ctx.tmplList || []).length,
      catalogLen: (ctx.agCatalog || []).length,
      matchedTemplateId: template && (template.id || template.name) || null,
      matchedTemplateType: template && (template.agreementType || template.type) || null,
      hasContent: !!(template && template.content),
      contentLen: (template && String(template.content || "").length) || 0,
    });

    // Fire risks
    var risksH = eli.get && eli.get("legal_risks", "runIntoCard");
    var risksP = (typeof risksH === "function")
      ? risksH({ targetId: RISKS_CARD, preloadOpts: { docType: formState.type } })
      : Promise.reject(new Error("legal_risks.runIntoCard not installed"));
    risksP.then(function (s) {
      _setHeaderSummary(RISKS_HEADER, (s && s.summary) || "Done", "ok");
    }).catch(function (err) {
      _setHeaderSummary(RISKS_HEADER, "⚠ " + ((err && err.message) || "failed"), "err");
      eli.log.event("tool", "legal_review_composite_risks_failed", { msg: err && err.message });
    });

    // Fire compare
    var compareH = eli.get && eli.get("compare", "runIntoCard");
    if (typeof compareH !== "function") {
      // runIntoCard wasn't registered — usually means the user is on
      // an older compare bundle. Surface explicitly in the card body
      // AND header so they can force-update.
      _setHeaderSummary(COMPARE_HEADER, "⚠ compare.runIntoCard missing", "err");
      var _cardBody = document.getElementById(COMPARE_CARD);
      if (_cardBody) {
        _cardBody.innerHTML =
          '<div style="padding:28px 22px;margin:8px;border:1px solid #fecaca;background:#fef2f2;">' +
            '<div style="font:800 11px/1 Inter,sans-serif;letter-spacing:.5px;text-transform:uppercase;color:#b91c1c;">⚠ Old compare bundle</div>' +
            '<div style="margin-top:8px;font:500 12px/1.5 Inter,sans-serif;color:#7f1d1d;">' +
              'The composite landing needs the <code>compare.runIntoCard</code> dispatch channel. Open Tool Manager → force-update <b>compare</b>, then re-launch.' +
            '</div>' +
          '</div>';
      }
      eli.log.event("tool", "legal_review_composite_compare_channel_missing", {});
      return;
    }
    function _firePicked(picked) {
      var payload = { template: picked };
      _setHeaderSummary(COMPARE_HEADER, "Running…", "warn");
      var body = document.getElementById(COMPARE_CARD);
      if (body) {
        body.innerHTML =
          '<div class="_eli3_lr_composite_pending">' +
            '<div class="_eli3_lr_composite_pending_spinner"></div>' +
            '<div>Comparing against "' + (picked.name || picked.id || "template") + '"…</div>' +
          '</div>';
      }
      compareH({ targetId: COMPARE_CARD, payload: payload, mode: "template" }).then(function (s) {
        _setHeaderSummary(COMPARE_HEADER, (s && s.summary) || "Done", "ok");
      }).catch(function (err) {
        _setHeaderSummary(COMPARE_HEADER, "⚠ " + ((err && err.message) || "failed"), "err");
        eli.log.event("tool", "legal_review_composite_compare_failed", { msg: err && err.message });
      });
    }
    if (comparePayload) {
      // Auto-match found a template — fire compare directly.
      _firePicked(comparePayload.template);
    } else if (ctx.tmplList && ctx.tmplList.length) {
      // No auto-match but templates are installed. Render an inline
      // picker so the user can choose without leaving the landing page.
      // (Mirrors what the manual Compare tile does, just embedded in
      // the card body.)
      _setHeaderSummary(COMPARE_HEADER, "Pick a template to compare", "warn");
      var pickerHost = document.getElementById(COMPARE_CARD);
      if (pickerHost) {
        var pickerId = "_eli3_lr_composite_compare_picker";
        var btnId = pickerId + "_btn";
        var opts = ctx.tmplList.map(function (t, i) {
          var lbl = (t.name || t.id || "(unnamed)") + (t.agreementType ? " — " + t.agreementType : "");
          return '<option value="' + i + '">' + String(lbl).replace(/</g, "&lt;") + '</option>';
        }).join("");
        pickerHost.innerHTML =
          '<div style="padding:22px 18px;">' +
            '<div style="font:800 10px/1 Inter,sans-serif;letter-spacing:.6px;text-transform:uppercase;color:#475569;margin-bottom:8px;">Pick a template to compare against</div>' +
            '<div style="font:500 11.5px/1.5 Inter,sans-serif;color:#64748b;margin-bottom:12px;">No template matched the selected agreement type automatically. Pick one below and click Compare.</div>' +
            '<select id="' + pickerId + '" style="width:100%;padding:8px 10px;font:500 12px Inter,sans-serif;border:1px solid #cbd5e1;background:#fff;">' + opts + '</select>' +
            '<button id="' + btnId + '" style="margin-top:10px;padding:8px 18px;background:linear-gradient(135deg,#1565c0,#0d47a1);color:#fff;border:0;font:700 11px/1 Inter,sans-serif;letter-spacing:.5px;text-transform:uppercase;cursor:pointer;">⚡ Compare</button>' +
          '</div>';
        document.getElementById(btnId).onclick = function () {
          var idx = parseInt(document.getElementById(pickerId).value, 10);
          var picked = ctx.tmplList[idx];
          if (picked) _firePicked(picked);
        };
      }
    } else {
      // No templates installed at all.
      _setHeaderSummary(COMPARE_HEADER, "No templates installed", "warn");
      var emptyHost = document.getElementById(COMPARE_CARD);
      if (emptyHost) {
        emptyHost.innerHTML = '<div style="padding:24px 18px;text-align:center;color:#64748b;font:500 12px/1.5 Inter,sans-serif;">' +
          'No templates are installed. Install templates via the data hub, then re-launch.' +
          '</div>';
      }
    }
  }

  function _cardShell(kind, icon, title, bodyId, summaryId, expanded) {
    return '<div class="_eli3_lr_composite_card" data-cardkind="' + kind + '" data-expanded="' + (expanded ? "1" : "0") + '">' +
      '<button type="button" class="_eli3_lr_composite_header" data-cardtoggle="' + kind + '">' +
        '<span class="_eli3_lr_composite_chev">▼</span>' +
        '<span class="_eli3_lr_composite_icon">' + icon + '</span>' +
        '<span class="_eli3_lr_composite_label">' + title + '</span>' +
        '<span class="_eli3_lr_composite_summary" id="' + summaryId + '">' +
          '<span class="_eli3_lr_composite_spinner"></span> running…' +
        '</span>' +
      '</button>' +
      '<div class="_eli3_lr_composite_body" id="' + bodyId + '" style="display:' + (expanded ? "block" : "none") + '">' +
        '<div class="_eli3_lr_composite_pending">' +
          '<div class="_eli3_lr_composite_pending_spinner"></div>' +
          '<div>Analyzing…</div>' +
        '</div>' +
      '</div>' +
    '</div>';
  }
  function _wireCardToggle(kind) {
    var btn = document.querySelector('[data-cardtoggle="' + kind + '"]');
    var card = document.querySelector('[data-cardkind="' + kind + '"]');
    if (!btn || !card) return;
    btn.onclick = function () {
      var open = card.getAttribute("data-expanded") === "1";
      card.setAttribute("data-expanded", open ? "0" : "1");
      var body = card.querySelector("._eli3_lr_composite_body");
      if (body) body.style.display = open ? "none" : "block";
      var chev = card.querySelector("._eli3_lr_composite_chev");
      if (chev) chev.textContent = open ? "▶" : "▼";
    };
  }
  function _setHeaderSummary(elId, text, severity) {
    var el = document.getElementById(elId);
    if (!el) return;
    var color = severity === "err" ? "#b91c1c" : severity === "warn" ? "#92400e" : "#166534";
    el.style.color = color;
    el.textContent = text;
  }

  // ─── Channels ───────────────────────────────────────────────────
  eli.register({
    tile: { app_legal_review: function () { _open(); } },
    // Programmatic launch (e.g., from build_draft post-save dispatch).
    legal_review: { open: _open },
  });

  // Back-compat shim for v2 callers that expect window.showLegalReview.
  window.showLegalReview = function () { _open(); };

  eli.log.event("tool", "legal_review_initialized", {});
}

