/* legal_review tool styles — triage landing page.
   Visual port of v2 runLegalReview (taskpane_v2.js:17206) using
   class-driven CSS instead of v2's inline-styles for maintainability.
   Injected as <style data-tool="legal_review">. */

/* Root fills the dashboard mount. _eli3_dashboard_root is flex-row by
   default, so this single child takes flex:1 to claim all of it.
   width/height 100% are belt-and-suspenders for any future layout
   where the parent's flex direction changes. min-height:0 keeps the
   inner scroll regions sane (children with overflow:auto need a flex
   parent that doesn't grow past viewport). */
._eli3_lr_root {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  width: 100%;
  height: 100%;
  min-height: 0;
  min-width: 0;
  background: #f8f9fa;
  font-family: Inter, sans-serif;
}

/* ── Top toolbar ──────────────────────────────────────────────────── */
._eli3_lr_toolbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 12px;
  border-bottom: 1px solid #e2e8f0;
  background: #fff;
  flex-shrink: 0;
}
._eli3_lr_back {
  background: none;
  border: none;
  color: #64748b;
  cursor: pointer;
  font: 800 11px/1 'Inter', sans-serif;
  letter-spacing: 1px;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 2px 4px;
  transition: color 0.15s;
}
._eli3_lr_back:hover { color: #1565c0; }
._eli3_lr_title {
  font-family: 'Book Antiqua', Georgia, serif;
  font-size: 13px;
  font-weight: 700;
  color: #1565c0;
}

/* ── Two-column grid ─────────────────────────────────────────────── */
._eli3_lr_grid {
  display: grid;
  grid-template-columns: minmax(0, 2.2fr) minmax(0, 1fr);
  flex: 1;
  overflow: hidden;
  min-height: 0;
}
@media (max-width: 450px), (max-height: 700px) {
  ._eli3_lr_right { display: none !important; }
  ._eli3_lr_grid { display: flex !important; flex-direction: column !important; }
}

/* ── Left column (Configure Analysis) ────────────────────────────── */
._eli3_lr_left {
  background: #fff;
  display: flex;
  flex-direction: column;
  border-right: 1px solid #e2e8f0;
  position: relative;
  min-width: 0;
}
._eli3_lr_accent {
  position: absolute;
  top: 0; left: 0;
  width: 4px;
  height: 100%;
  z-index: 10;
}
._eli3_lr_scroll {
  flex: 1;
  overflow-y: auto;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}
._eli3_lr_h2 {
  font-family: 'Book Antiqua', Georgia, serif;
  font-size: 20px;
  color: #0f172a;
  margin: 0 0 4px 0;
}
._eli3_lr_intro {
  font-size: 11px;
  color: #64748b;
  margin: 0;
  line-height: 1.4;
}

/* Card: each numbered step */
._eli3_lr_card {
  background: #f8fafc;
  padding: 12px;
  border: 1px solid #e2e8f0;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.08);
}
._eli3_lr_card_head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 8px;
  min-height: 20px;
}
._eli3_lr_step {
  font: 800 10px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #0d47a1;
}
._eli3_lr_step_block { display: block; margin-bottom: 8px; }
._eli3_lr_badgerow {
  display: inline-flex;
  gap: 6px;
}
._eli3_lr_badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
