  font: 700 10px/1 'Inter', sans-serif;
  letter-spacing: 0.3px;
}
._eli3_lr_badge_pb {
  background: #ecfdf5;
  border: 1px solid #6ee7b7;
  color: #065f46;
}
._eli3_lr_badge_tpl {
  background: #eff6ff;
  border: 1px solid #93c5fd;
  color: #1e40af;
