/* Agreement type select */
._eli3_lr_selectwrap { position: relative; }
._eli3_lr_select {
  width: 100%;
  padding: 8px;
  font: 700 12px/1.2 'Inter', sans-serif;
  background: #fff;
  border: 2px solid #1565c0;
